  const fetchPromise = fetchToken();
  store.pending = fetchPromise;

  try {
    const value = await fetchPromise;
    store.cached = { value, expiresAt: Date.now() + ttlMs };
    return value;
  } finally {
    store.pending = null;
  }
}

